from typing import Callable, Dict, List, Sequence

def diagonal(accepts: Callable[[int, int], bool],
             programs: Sequence[int]) -> Dict[int, bool]:
    return {q: (not accepts(q, q)) for q in programs}

def realized(accepts: Callable[[int, int], bool],
             programs: Sequence[int], behavior: Dict[int, bool]) -> bool:
    return any(all(accepts(p, q) == behavior[q] for q in programs)
               for p in programs)

if __name__ == "__main__":
    P: List[int] = list(range(6))
    base = lambda p, q: (p * q + 1) % 3 == 0
    print("diagonal realized?", realized(base, P, diagonal(base, P)))
    for name, oracle in {"true": lambda p: True,
                          "parity": lambda p: p % 2 == 0}.items():
        acc = lambda p, q, o=oracle: o(p) ^ ((p + q) % 2 == 0)
        print(name, "jump realized?", realized(acc, P, diagonal(acc, P)))

from typing import List

def level_cardinalities(base_size: int, num_levels: int) -> List[int]:
    sizes = [base_size]
    for _ in range(num_levels):
        sizes.append(2 ** sizes[-1])
    return sizes

if __name__ == "__main__":
    sizes = level_cardinalities(2, 4)
    for n, s in enumerate(sizes):
        d = s.bit_length() * 3 // 10 + 1
        print(f"|Level {n}| =", s if d <= 40 else f"a {d:,}-digit number")
    print("strictly increasing?",
          all(sizes[i] < sizes[i + 1] for i in range(len(sizes) - 1)))

from itertools import product
from typing import Callable, List, Sequence, Tuple

def find_fixed_point(f: Callable[[int], int],
                     domain: Sequence[int]) -> List[int]:
    return [e for e in domain if f(e) == e]

def all_endofunctions(n: int) -> List[Tuple[int, ...]]:
    return list(product(range(n), repeat=n))

if __name__ == "__main__":
    printer = {0: 1, 1: 1, 2: 3, 3: 0}
    print("quines:", find_fixed_point(lambda e: printer[e], range(4)))
    ok = all(find_fixed_point(lambda e, g=g: g[e], [0])
             for g in all_endofunctions(1))
    print("unit system: every transformation has a fixed program?", ok)

