from typing import List, Sequence

def anti_diagonal(phi: Sequence[Sequence[bool]]) -> List[bool]:
    """Return g with g[x] = not phi[x][x], guaranteed outside the rows of phi."""
    return [not phi[x][x] for x in range(len(phi))]

def certify_escapes(phi: Sequence[Sequence[bool]]) -> List[bool]:
    """Return the escaping witness after checking it differs from every row."""
    g = anti_diagonal(phi)
    for a in range(len(phi)):
        assert g[a] != phi[a][a], f"failed to escape row {a}"
    return g

