function JUMP(accepts, programs):
    return { q -> NOT accepts(q, q) : q in programs }

function REALIZED(accepts, programs, behavior):
    for p in programs:
        if for all q in programs: accepts(p, q) == behavior[q]:
            return True
    return False

function BARRIER_HOLDS(programs, oracles, accepts_of):
    for oracle in oracles:
        accepts <- accepts_of(oracle)
        if REALIZED(accepts, programs, JUMP(accepts, programs)):
            return False        # barrier would be violated
    return True

