from typing import Callable, Dict, Iterable, Sequence

def jump(accepts: Callable[[int, int], bool],
         programs: Sequence[int]) -> Dict[int, bool]:
    return {q: (not accepts(q, q)) for q in programs}

def realized(accepts: Callable[[int, int], bool],
             programs: Sequence[int], behavior: Dict[int, bool]) -> bool:
    return any(all(accepts(p, q) == behavior[q] for q in programs)
               for p in programs)

def barrier_holds(
    programs: Sequence[int],
    oracles: Iterable[Callable[[int], bool]],
    accepts_of: Callable[[Callable[[int], bool]], Callable[[int, int], bool]],
) -> bool:
    """True iff no oracle-program realizes the jump, for every given oracle."""
    for oracle in oracles:
        accepts = accepts_of(oracle)
        if realized(accepts, programs, jump(accepts, programs)):
            return False
    return True

