from typing import List

def level_cardinalities(base_size: int, num_levels: int) -> List[int]:
    """|Level 0| = base_size; |Level (n+1)| = 2 ** |Level n|."""
    sizes: List[int] = [base_size]
    for _ in range(num_levels):
        sizes.append(2 ** sizes[-1])
    return sizes

def strictly_increasing(sizes: List[int]) -> bool:
    return all(sizes[i] < sizes[i + 1] for i in range(len(sizes) - 1))

