import matplotlib.pyplot as plt
import numpy as np

def plot_fixed_points(f: dict, title: str = "Program transformation f") -> None:
    n = len(f)
    angles = np.linspace(0, 2 * np.pi, n, endpoint=False)
    pos = {k: (np.cos(a), np.sin(a)) for k, a in zip(sorted(f), angles)}
    plt.figure(figsize=(6, 6))
    for src, dst in f.items():
        x0, y0 = pos[src]; x1, y1 = pos[dst]
        if src == dst:
            plt.scatter([x0], [y0], s=600, facecolors="none",
                        edgecolors="red", linewidths=2)
        else:
            plt.annotate("", xy=(x1, y1), xytext=(x0, y0),
                         arrowprops=dict(arrowstyle="->", color="gray"))
    for k, (x, y) in pos.items():
        plt.scatter([x], [y], s=300, color="lightblue", zorder=3)
        plt.text(x, y, str(k), ha="center", va="center", zorder=4)
    plt.title(title + "  (red circles = quines / fixed programs)")
    plt.axis("equal"); plt.axis("off")
    plt.tight_layout(); plt.savefig("fixed_points.png", dpi=150)

if __name__ == "__main__":
    plot_fixed_points({0: 1, 1: 1, 2: 3, 3: 0})
